    ['The Shadow Awaits'] = {
        id = 15,
        start_npc = 'Any Windurst Gate Guard',
        start_zone = 'Castle Zvahl Keep',
        start_pos = nil,
        description = 'As written in the stars and interpreted by the Star Sibyl, you are to destined to journey to Castle Zvahl, which towers over Xarcabard, the end of the known lands. There, you are to witness what fate has in store for our world.',
        reward = 'Rank 6\nUnlock Zilart Missions\nUnlock Dynamis\n20,000 Gil\nTrust: Ajido-Marujido',
        fame = nil,
        fame_level = nil,
        title = 'Star-ordained Warrior, Shadow Banisher',
        repeatable = 'No',
        previous = {'The Final Seal'},
        next = {'Full Moon Fountain'},
        requirements = nil,
        walkthrough = 'Trade 2+ Crystals to the Conquest NPC to raise your Rank bar and unlock the Mission, then accept it from the Gate Guard. You will receive [Key Item] Star crested summons.\n1. Head to the top of the Heavens Tower in Windurst Walls HP #1 and click the Door: Vestal Chamber.\n   - If you\'re not using Trusts and are level 55-60, form a full party of players.\nYou will have to reach the Throne Room in Castle Zvahl Keep and clear the BCNM "The Shadow Lord Battle".\n2. Castle Zvahl Keep Home Point #1 is fastest way. If you don\'t have the HP unlocked already, check the instructions below.\n3. After you clear the BCNM, you\'ll get another cutscene. At the end, you\'ll be returned to the entrance of Castle Zvahl Baileys. You will also receive the [Key Item] Shadow fragment.\n   - You can start the Zilart Missions and continue with Rhapsodies of Vanadiel Mission 1-12 from this point on, ranking up is optional.\n4. Zone into Heavens Tower for a brief cutscene.\n5. Click the Door: Vestal Chamber for a final cutscene and your reward: Rank 6 and 20,000 Gil.\n   - Don\'t forget to speak to Apururu in Windurst Woods at (H-9) to learn Trust: Ajido-Marujido.\n   - Also if you\'ve obtained the trust permits (the Red and Blue) from the other 2 nations you can acquire Trion and Volker as trusts now by visiting their respective starting NPC\'s.',
        notes = nil,
    },
    ['The Sixth Ministry'] = {
        id = 18,
        start_npc = 'Any Windurst Gate Guard',
        start_zone = 'Windurst Waters',
        start_pos = 'G-8',
        description = 'At the request of the Optistery,\nyou are to find former minister\nKaraha-Baruha\'s laboratory in\nToraimarai Canal, and delve deeper\ninto the mystery of the Book of\nthe Gods.',
        reward = 'Rank Points',
        fame = nil,
        fame_level = nil,
        title = 'None',
        repeatable = 'No',
        previous = {'Saintly Invitation'},
        next = {'Awakening of the Gods'},
        requirements = nil,
        walkthrough = 'Trade enough Crystals to the Conquest NPC to raise your Rank bar and unlock the Mission, then accept it from the Gate Guard.\n1. Talk to Tosuka-Porika in the Optistery eastern building in Windurst Waters HP #1 (G-8) for a cutscene and to receive the [Key Item] Optistery ring.\n2. Head to Toraimarai Canal (G-8) Map 2 and defeat the 4 Hinge Oils in the room.\n   - Quickest way to get there is to enter through the Windurst Walls (I-3) Priming Gate using the [Key Item] Rhinostery certificate, take a right at the bottom of the stairs, get into the water and keep turning left until you reach some stairs, which you should go up. From here, head south → east → north to reach the Slimes in (G-8).\n   - Alternatively if you have the Home Point #1 of Toraimarai Canal, go south from it entering a big room, continue towards your left to exit the room and begin walking through the canals. On Map 1 of the canals stay on the above path and walk towards point B. Once you reach point B on the above section keep going north on the only path and go down in the water section of the canals, go back to B and cross into Map 2, take a first right and go south, at the first stairs go up to the raised path and go towards (G-8) where you will find the oozes and door.\n3. After defeating the 4 Slimes, head northeast to the stairs at (H-8) and examine the Marble Door at the top.\n   - All four Hinge Oils must be defeated before you can enter The Animastery. Hinge Oils will repop after 16 minutes.\n4. Examine the Tome of Magic lying on the ground to begin a cutscene.\n   - This is near the desk and a skull resting on a chair.\nReturn to Tosuka-Porika to complete the Mission. You will receive the [Key Item] Blank Book of the Gods.',
        notes = nil,
    },
    ['The Three Kingdoms'] = {
        id = 5,
        start_npc = 'Any Windurst Gate Guard',
        start_zone = 'Heavens Tower',
        start_pos = nil,
        description = 'Determine the state of affairs in San d\'Oria and Bastok, and render assistance on behalf of Heavens Tower. Inquire at our consulate in each country for more information. Traveling by ship from Mhaura to Selbina is recommended.',
        reward = 'Rank 3\n3,000 Gil\n[Key Item] Adventurer\'s Certificate',
        fame = nil,
        fame_level = nil,
        title = 'Dread Dragon Slayer or Dark Dragon Slayer, Warchief Wrecker, Certified Adventurer',
        repeatable = 'No',
        previous = {'A Testing Time'},
        next = {'To Each His Own Right'},
        requirements = nil,
        walkthrough = 'Trade three Crystals (3+ if you skipped the previous mission) to the Conquest NPC to raise your Rank bar and unlock the Mission, then accept it from the Gate Guard.\n1. This Mission can be long if you do not have Home Points, and is broken down in to two legs. Whichever Nation you choose first determines how the next plays out. Option 2, the San d\'Oria path progression, is typically easier and faster.\n2. Speak with Kupipi in Heavens Tower. She is inside the Clerical Chamber. She will give you a [Key Item] Letter to the consuls.\n   - You may receive Cipher: Semih if you don\'t already have it and are participating in Trust.\n\nWindurst to Bastok:\n\n1. Speak to Patt-Pott in Bastok Metalworks HP#1. He is inside the Windurstian Consulate top floor (I-7).\n2. Speak to Pius in the President\'s Office Department of Industry (J-8).\n3. Speak to Grohm at (H-9) in the Craftsmen\'s Eatery. He will give you 3 Pickaxes. Consider buying more, as they can break.\n4. Make your way to Palborough Mines in North Gustaberg, at the very north of the zone. You will need to mine Mine Gravel from the Mythril Seams located throughout the zone. There is one on the first floor at (I-8), and one on the top floor at (I-9). Trade the Pickaxe to the Seam until you receive some Mine Gravel.\n   - You CAN purchase Mine Gravel from the Auction House. ( ➞ Others ➞ Misc. 1)\n   - If you care about the  ultimately used for the Omega Mount, set that objective before you do the next step - it requires 10 Mine Gravel turned into Mythril Sand.\n5. Once you receive the Mine Gravel, head to the second floor, and make your way to (I-7). Trade the gravel to the refiner and then pull the lever. Drop off the ledge to the level below and pull another lever. You will receive Mythril Sand.\n6. Trade the Mythril Sand to Patt-Pott. Talk to him once more. This is the end of the Bastok leg.\n\nBastok to San d\'Oria:\n\n7. Speak to Kasaroro in the Windurstian Consulate in Northern San d\'Oria (H-9).\n8. Speak to Halver in Chateau d\'Oraguille.\n   - You will receive Cipher: Halver if you don\'t already have it. If not received, it may be received later.\n9. Go to Horlais Peak and clear the BCNM "The Rank 2 Final Mission".\n   - If you are low level consider forming a party (and/or use Trusts) of level 25 or higher, but make sure everyone has gear for a level 25 fight. A BLM or RDM is ideal for this fight, as you\'ll want sleep.\n   - To get to Horlais Peak use the Homepoint to Yughott Grotto or make your way to Ghelsba Outpost from West Ronfaure, it is in the northwestern corner. Inside, follow the left wall until you zone in to Yughott Grotto. Follow it all the way to the end, around (K-5). You should exit to Fort Ghelsba.\n   - Outside, head straight and stick to the left wall. You should start going up hill. Follow it around. At the top, there will be a large hut to your right. Enter it and go to the back, there is a hidden entrance here. It returns to Yughott Grotto#4. Head for (J-6) to enter Horlais Peak.\n   - Prepare and enter. Buffs will wear on zone, so buff up inside. Make your way to the top to face off against two NMs, an  called Seeker and a  called Dread Dragon.\n   - Sleep the Dragon and then defeat the Seeker, who is weak. Attack the dragon and take it down. This fight is really easy with a full party.\n   - If you are low level it can easily be defeated with a MNK/WAR and WHM/BLM. Can be soloed by some jobs with a lot of meds, and duoed by almost any melee job with a WHM healer.\n10. Return to Kasaroro at Northern San d\'Oria after clearing the BCNM.\n11. Return to Kupipi in Heavens Tower to complete the Mission.\n\nWindurst to San d\'Oria:\n\n1. Make your way to San d\'Oria and visit the Windurstian Consulate in Northern San d\'Oria.\n2. Speak to Heruze-Moruze and then Kasaroro, both at (H-9).\n3. Head over to Chateau d\'Oraguille and speak to Halver.\n   - This NPC is involved in multiple different Quests and Missions, you may need to speak to him repeatedly until he sends you to Ghelsba Outpost.\n   - Ghelsba Outpost is located to the far northwestern corner of West Ronfaure.\n4. Inside, head for (H-7) and look for the NM Warchief Vatgit and defeat him (its only purpose is for this Mission, and is usually up and wandering around. If not, wait a short time, it doesn\'t take long).\n   - The Survival Guide to Fort Ghelsba will bring you close to the NM. Just zone back out to Ghelsba and across the bridge.\n5. Speak to Kasaroro again. You are now finished with the San d\'Oria half of this Mission.\n\nSan d\'Oria to Bastok:\n\n6. Make your way to Bastok. Enter the Metalworks from Bastok Markets. Make your way to the top and speak with Patt-Pott inside the Windurstian Consulate, around (I-7).\n7. Speak to Pius in the President\'s Office Department of Industry (J-8). He will send you to the Craftsmen\'s Eatery (H-9) to speak to Grohm.\n   - If you\'re low level, form a party (and/or use Trusts) of level 25 or higher, but make sure everyone has gear for a level 25 fight. A BLM or RDM is ideal for this fight, as you\'ll want sleep.\n8. Make your way to Palborough Mines, in the very far north of North Gustaberg.\n   - If you\'ve already been there, take Palborough Mines Home Point #1.\n9. Inside, make your way to (I-8) and head upstairs. Here, make your way to (H-10) and zone in to Waughroon Shrine.\n10. Prepare and enter. Buffs will wear on zone, so buff up inside. Make your way to the top to face off against two NMs, an  called Seeker and a  called Dark Dragon.\n   - This fight is trivial with trusts\n   - Sleep the Dragon and then defeat the Seeker, who is weak. Attack the dragon and take it down. This fight is really easy with a full party.\n   - It can easily be defeated with a MNK/WAR and WHM/BLM. Can be soloed by some jobs with a lot of meds, and duoed by almost any melee job with a WHM healer.\n11. Once cleared, return to Patt-Pott in Metalworks.\n12. Your journey is almost complete, head back to Heavens Tower in Windurst Walls and speak to Kupipi to complete the Mission and receive your rewards.',
        notes = nil,
    },
